update.foreach:
UPDATE T_CX_EMBRYO_MONTH_PLAN_SURPLUS
SET
MONTH_PLAN_QTY = #{item.monthPlanQty},
MONTH_PLAN_VERSION = #{item.monthPlanVersion},
LAST_MONTH_STOCK = #{item.lastMonthStock},
MONTH_FINISH_QTY = #{item.monthFinishQty},
MONTH_REMAIN_QTY = #{item.monthRemainQty},
DATA_SOURCE = #{item.dataSource},
UPDATE_TIME = NOW()
WHERE
YEAR = #{item.year}
AND MONTH = #{item.month}
AND FACTORY_CODE = #{item.factoryCode}
AND MATERIAL_CODE = #{item.materialCode}
AND BOM_DATA_VERSION = #{item.bomDataVersion}
